void setup() {
  pinMode(2, OUTPUT);
}

void loop() {
  // 1 second on, 1 second off
  digitalWrite(2, HIGH);
  delay(1000);
  digitalWrite(2, LOW);
  delay(1000);

  // 0.5 second on, 0.5 second off
  digitalWrite(2, HIGH);
  delay(500);
  digitalWrite(2, LOW);
  delay(500);

  // 0.25 second on, 0.25 second off
  digitalWrite(2, HIGH);
  delay(250);
  digitalWrite(2, LOW);
  delay(250);

  // 0.125 second on, 0.125 second off
  digitalWrite(2, HIGH);
  delay(125);
  digitalWrite(2, LOW);
  delay(125);
}
